select , datediff(expiredate, curdate()) expiredays,
from sdsshop.u_s_site where shop_code = #{query.shopCode}
and sitename like concat('%', #{query.siteName}, '%')
and domain like concat('%', #{query.domain}, '%')
and status = #{query.status}
and ownername like concat('%', #{query.ownerName}, '%') order by sortnum asc, case when expiredate is null then 1 else 0 end asc, expiredate asc, createtime desc, sitecode desc

select consolesecret
  from sdsshop.u_s_site
 where shop_code = #{shopCode} and sitecode = #{siteCode}

select 
  from sdsshop.u_s_site
 where shop_code = #{shopCode}
   and domain = #{domain}
   and #{domain} is not null
 limit 1

